        do_pack = FLB_FALSE;
    }

    while (c < end) {
        label = c;
        while ((c < end) && ltvs_label[*c]) {
            c++;
        }
        label_len = c - label;
        if (c == end) {
            break;
        }

        if (*c != ':') {
